/* From Uiverse.io by vk-uiux - Tags: animation, loader, animated, circle loader, rainbow, html, css, css effect, multicolor */
.__UIV_SCOPE__ .loader-inner {
  width: 100px;
  height: 60px;
  margin: auto;
  position: absolute;
  inset: 0;
}

.__UIV_SCOPE__ .loader-line-wrap {
  animation: spin 2000ms cubic-bezier(0.175, 0.885, 0.32, 1.275) infinite;
  width: 100px;
  height: 50px;
  left: 0;
  overflow: hidden;
  position: absolute;
  top: 0;
  transform-origin: 50% 100%;
}

.__UIV_SCOPE__ .loader-line {
  border: 4px solid transparent;
  border-radius: 100%;
  width: 100px;
  height: 100px;
  margin: 0 auto;
  position: absolute;
  inset: 0;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(1) {
  animation-delay: -50ms;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(2) {
  animation-delay: -100ms;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(3) {
  animation-delay: -150ms;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(4) {
  animation-delay: -200ms;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(5) {
  animation-delay: -250ms;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(1) .loader-line {
  border-color: #eb4747;
  height: 90px;
  width: 90px;
  top: 7px;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(2) .loader-line {
  border-color: #ebeb47;
  height: 76px;
  width: 76px;
  top: 14px;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(3) .loader-line {
  border-color: #47eb47;
  height: 62px;
  width: 62px;
  top: 21px;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(4) .loader-line {
  border-color: #47ebeb;
  height: 48px;
  width: 48px;
  top: 28px;
}

.__UIV_SCOPE__ .loader-line-wrap:nth-child(5) .loader-line {
  border-color: #4747eb;
  height: 34px;
  width: 34px;
  top: 35px;
}

@keyframes spin {
  0%,
  15% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(360deg);
  }
}
